CREATE TABLE IF NOT EXISTS public.sales_contracts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, sale_id uuid NOT NULL UNIQUE REFERENCES public.sales(id) ON DELETE CASCADE, contract_number text NOT NULL, status text NOT NULL DEFAULT 'DRAFT', signed_at timestamptz, file_path text, notes text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id, contract_number));